CREATE SEQUENCE adjustment_numbers;
CREATE TABLE stock_adjustments(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),code text NOT NULL UNIQUE DEFAULT('ADJ-'||lpad(nextval('adjustment_numbers')::text,8,'0')),project_id uuid NOT NULL REFERENCES projects(id),exception_id uuid NOT NULL REFERENCES inventory_exceptions(id),reason text NOT NULL,status text NOT NULL DEFAULT 'DRAFT' CHECK(status IN('DRAFT','PENDING','APPLIED','REJECTED')),reverses_id uuid REFERENCES stock_adjustments(id),created_by uuid NOT NULL REFERENCES users(id),created_at timestamptz NOT NULL DEFAULT clock_timestamp(),approved_by uuid REFERENCES users(id),approved_at timestamptz,applied_revision bigint REFERENCES inventory_revisions(id),applied_txid bigint,approved_attachments jsonb,review_note text,version int NOT NULL DEFAULT 1,CHECK(status<>'APPLIED' OR(approved_by IS NOT NULL AND approved_by<>created_by AND applied_revision IS NOT NULL)));
CREATE UNIQUE INDEX one_applied_reverse ON stock_adjustments(reverses_id) WHERE status='APPLIED' AND reverses_id IS NOT NULL;
CREATE TABLE adjustment_lines(id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,adjustment_id uuid NOT NULL REFERENCES stock_adjustments(id),bundle_no text NOT NULL,kind text NOT NULL CHECK(kind IN('GAIN','LOSS','WEIGHT','LOCATION','RESTORE')),before_data jsonb NOT NULL,after_data jsonb NOT NULL,expected_version int,UNIQUE(adjustment_id,bundle_no));
CREATE TABLE adjustment_steps(id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,adjustment_id uuid NOT NULL REFERENCES stock_adjustments(id),action text NOT NULL,actor_id uuid NOT NULL REFERENCES users(id),note text NOT NULL,occurred_at timestamptz NOT NULL DEFAULT clock_timestamp());
CREATE TRIGGER adjustment_state BEFORE UPDATE OR DELETE ON stock_adjustments FOR EACH ROW EXECUTE FUNCTION v23_state_owner();
CREATE TRIGGER adjustment_lines_history BEFORE UPDATE OR DELETE ON adjustment_lines FOR EACH ROW EXECUTE FUNCTION v23_immutable();
CREATE TRIGGER adjustment_steps_history BEFORE UPDATE OR DELETE ON adjustment_steps FOR EACH ROW EXECUTE FUNCTION v23_immutable();
CREATE TRIGGER temporal_document AFTER INSERT OR UPDATE ON stock_adjustments FOR EACH ROW EXECUTE FUNCTION v24_source_capture();
ALTER TABLE bundles ADD COLUMN original_net_weight numeric(14,6),ADD COLUMN adjustment_origin_id uuid REFERENCES stock_adjustments(id);
CREATE OR REPLACE FUNCTION confirmed_bundle_guard() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN
 IF TG_OP='DELETE' THEN RAISE EXCEPTION 'Bundle history cannot be deleted' USING ERRCODE='23514';END IF;
 IF current_user='musonoi_owner' AND OLD.original_net_weight IS NULL AND NEW.original_net_weight=OLD.net_weight AND(to_jsonb(NEW)-'original_net_weight')=(to_jsonb(OLD)-'original_net_weight') THEN RETURN NEW;END IF;
 IF current_user='musonoi_owner' THEN
 IF(to_jsonb(NEW)-ARRAY['version','sample_status','location_id','physical_status','net_weight'])<>(to_jsonb(OLD)-ARRAY['version','sample_status','location_id','physical_status','net_weight']) THEN RAISE EXCEPTION 'Original bundle archive immutable' USING ERRCODE='23514';END IF;
 IF NEW.net_weight<>OLD.net_weight AND NOT EXISTS(SELECT 1 FROM stock_adjustments a JOIN adjustment_lines l ON l.adjustment_id=a.id WHERE a.status='APPLIED' AND a.applied_txid=txid_current() AND l.bundle_no=OLD.bundle_no AND(l.before_data->>'net_weight')::numeric=OLD.net_weight AND(l.after_data->>'net_weight')::numeric=NEW.net_weight) THEN RAISE EXCEPTION 'Weight projection changes require an applied authorized adjustment' USING ERRCODE='23514';END IF;
 IF(NEW.physical_status='ADJUSTED_OUT' OR OLD.physical_status='ADJUSTED_OUT') AND NEW.physical_status<>OLD.physical_status AND NOT EXISTS(SELECT 1 FROM stock_adjustments a JOIN adjustment_lines l ON l.adjustment_id=a.id WHERE a.status='APPLIED' AND a.applied_txid=txid_current() AND l.bundle_no=OLD.bundle_no AND l.after_data->>'physical_status'=NEW.physical_status) THEN RAISE EXCEPTION 'Adjustment removal/restore requires approval' USING ERRCODE='23514';END IF;
 ELSE IF(to_jsonb(NEW)-'version')<>(to_jsonb(OLD)-'version') THEN RAISE EXCEPTION 'Direct inventory changes forbidden' USING ERRCODE='23514';END IF;END IF;
 IF NEW.version<>OLD.version+1 AND NEW.version<>OLD.version THEN RAISE EXCEPTION 'Invalid bundle version' USING ERRCODE='23514';END IF;RETURN NEW;END $$;
UPDATE bundles SET original_net_weight=net_weight;
ALTER TABLE bundles ALTER COLUMN original_net_weight SET NOT NULL;
CREATE FUNCTION original_weight_insert() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN NEW.original_net_weight:=NEW.net_weight;RETURN NEW;END $$;
CREATE TRIGGER original_bundle_weight BEFORE INSERT ON bundles FOR EACH ROW EXECUTE FUNCTION original_weight_insert();
ALTER TABLE bundles DROP CONSTRAINT bundles_physical_status_check;
ALTER TABLE bundles ADD CHECK(physical_status IN('IN_STOCK','OUTBOUND','ADJUSTED_OUT'));
ALTER TABLE inventory_events DROP CONSTRAINT inventory_events_event_type_check;
ALTER TABLE inventory_events DROP CONSTRAINT inventory_events_check;
ALTER TABLE inventory_events ADD CHECK(event_type IN('INBOUND','LOCK','UNLOCK','SAMPLE','WEIGH','LOAD','UNLOAD','MOVE','OUTBOUND','REVERSAL','ADJUST_GAIN','ADJUST_LOSS','ADJUST_WEIGHT','ADJUST_LOCATION','ADJUST_RESTORE'));
ALTER TABLE inventory_events ADD CHECK((event_type IN('INBOUND','REVERSAL','ADJUST_GAIN','ADJUST_RESTORE') AND physical_delta>0) OR(event_type IN('OUTBOUND','ADJUST_LOSS') AND physical_delta<0) OR(event_type='ADJUST_WEIGHT' AND physical_delta<>0) OR(event_type IN('LOCK','UNLOCK','SAMPLE','WEIGH','LOAD','UNLOAD','MOVE','ADJUST_LOCATION') AND physical_delta=0));
CREATE UNIQUE INDEX one_adjustment_event ON inventory_events(bundle_id,(after_data->>'adjustment_id')) WHERE event_type LIKE 'ADJUST_%';
CREATE FUNCTION adjustment_create(actor uuid,p uuid,exc uuid,reason text,entries jsonb,reverses uuid DEFAULT NULL) RETURNS stock_adjustments LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,pg_temp AS $$ DECLARE d stock_adjustments;e inventory_exceptions;x jsonb;b bundles;before jsonb;after jsonb;no text;kind text;BEGIN
 PERFORM v24_revision();PERFORM v23_require(actor,'adjust:write',p,NULL,NULL);SELECT * INTO e FROM inventory_exceptions WHERE id=exc AND project_id=p;
 IF NOT FOUND OR e.status IN('RESOLVED','CLOSED') OR length(trim(reason)) NOT BETWEEN 1 AND 2000 OR jsonb_typeof(entries)<>'array' OR jsonb_array_length(entries) NOT BETWEEN 1 AND 100 THEN RAISE EXCEPTION 'Active related exception, reason and 1-100 lines required' USING ERRCODE='23514';END IF;
 IF reverses IS NOT NULL AND NOT EXISTS(SELECT 1 FROM stock_adjustments WHERE id=reverses AND project_id=p AND status='APPLIED') THEN RAISE EXCEPTION 'Only applied adjustment may be reversed' USING ERRCODE='23514';END IF;
 INSERT INTO stock_adjustments(project_id,exception_id,reason,reverses_id,created_by) VALUES(p,exc,reason,reverses,actor) RETURNING * INTO d;
 FOR x IN SELECT * FROM jsonb_array_elements(entries) LOOP
 no:=upper(trim(x->>'bundle_no'));kind:=x->>'kind';IF no IS NULL OR no!~'^[A-Z0-9][A-Z0-9._/-]{0,79}$' THEN RAISE EXCEPTION 'Invalid bundle number' USING ERRCODE='23514';END IF;
 SELECT * INTO b FROM bundles WHERE bundle_no=no FOR UPDATE;
 IF kind='GAIN' THEN IF FOUND OR EXISTS(SELECT 1 FROM receipt_lines l JOIN receipts r ON r.id=l.receipt_id WHERE l.bundle_no=no AND r.status='PENDING') THEN RAISE EXCEPTION 'Bundle number already used or has pending receipt' USING ERRCODE='23514';END IF;before:='{}';after:=jsonb_build_object('net_weight',x->>'net_weight','location_id',x->>'location_id','batch_id',x->>'batch_id','customer_id',x->>'customer_id','production_date',x->>'production_date','physical_status','IN_STOCK');
 ELSE IF NOT FOUND OR b.project_id<>p OR(kind<>'RESTORE' AND b.physical_status<>'IN_STOCK') OR(kind='RESTORE' AND(b.physical_status<>'ADJUSTED_OUT' OR reverses IS NULL OR NOT EXISTS(SELECT 1 FROM adjustment_lines WHERE adjustment_id=reverses AND bundle_no=no AND kind='LOSS'))) THEN RAISE EXCEPTION 'Bundle unavailable; formal outbound must use V2.3 physical return' USING ERRCODE='23514';END IF;
 IF EXISTS(SELECT 1 FROM reservations WHERE bundle_id=b.id AND released_at IS NULL) OR EXISTS(SELECT 1 FROM loading_items WHERE bundle_id=b.id AND active) THEN RAISE EXCEPTION 'Unlock or unload before adjustment' USING ERRCODE='23514';END IF;
 before:=jsonb_build_object('net_weight',b.net_weight::text,'location_id',b.location_id,'batch_id',b.batch_id,'customer_id',b.customer_id,'physical_status',b.physical_status,'version',b.version,'original_net_weight',b.original_net_weight::text);after:=before;
 IF kind='WEIGHT' THEN after:=after||jsonb_build_object('net_weight',x->>'net_weight');ELSIF kind='LOCATION' THEN after:=after||jsonb_build_object('location_id',x->>'location_id');ELSIF kind='LOSS' THEN after:=after||jsonb_build_object('physical_status','ADJUSTED_OUT');ELSIF kind='RESTORE' THEN after:=after||jsonb_build_object('physical_status','IN_STOCK');ELSE RAISE EXCEPTION 'Unknown adjustment kind' USING ERRCODE='23514';END IF;
 IF kind='WEIGHT' AND(after->>'net_weight')::numeric=b.net_weight OR kind='LOCATION' AND(after->>'location_id')::uuid=b.location_id THEN RAISE EXCEPTION 'Adjustment must change a value' USING ERRCODE='23514';END IF;END IF;
 IF coalesce(after->>'net_weight','')!~'^\d{1,8}(\.\d{1,6})?$' OR(after->>'net_weight')::numeric<=0 OR NOT EXISTS(SELECT 1 FROM locations l JOIN warehouses w ON w.id=l.warehouse_id WHERE l.id=(after->>'location_id')::uuid AND l.project_id=p AND l.active AND w.active AND NOT EXISTS(SELECT 1 FROM yards y WHERE y.id=l.yard_id AND NOT y.active)) OR NOT EXISTS(SELECT 1 FROM batches WHERE id=(after->>'batch_id')::uuid AND project_id=p AND active) OR NOT EXISTS(SELECT 1 FROM customers WHERE id=(after->>'customer_id')::uuid AND project_id=p AND active) THEN RAISE EXCEPTION 'Invalid weight or inactive master data' USING ERRCODE='23514';END IF;
 INSERT INTO adjustment_lines(adjustment_id,bundle_no,kind,before_data,after_data,expected_version) VALUES(d.id,no,kind,before,after,CASE WHEN kind='GAIN' THEN NULL ELSE b.version END);
 END LOOP;
 INSERT INTO adjustment_steps(adjustment_id,action,actor_id,note) VALUES(d.id,'CREATE',actor,reason);INSERT INTO audit_logs(actor_id,action,entity_type,entity_id,after_data) VALUES(actor,'adjustment_drafted','stock_adjustments',d.id::text,to_jsonb(d));RETURN d;END $$;
CREATE FUNCTION adjustment_action(actor uuid,doc uuid,expected int,action text,note text) RETURNS stock_adjustments LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,pg_temp AS $$ DECLARE d stock_adjustments;l adjustment_lines;b bundles;bid uuid;qty numeric;delta numeric;r bigint;BEGIN
 r:=v24_revision();SELECT * INTO d FROM stock_adjustments WHERE id=doc FOR UPDATE;IF NOT FOUND OR d.version<>expected OR length(trim(note)) NOT BETWEEN 1 AND 2000 THEN RAISE EXCEPTION 'Adjustment version or explanation invalid' USING ERRCODE='23514';END IF;PERFORM v23_require(actor,CASE WHEN action IN('approve','reject') THEN 'adjust:approve' ELSE 'adjust:write' END,d.project_id,NULL,NULL);
 IF action='submit' THEN IF d.status<>'DRAFT' OR(actor<>d.created_by AND NOT EXISTS(SELECT 1 FROM users WHERE id=actor AND role_code='admin')) THEN RAISE EXCEPTION 'Only authorized draft submission' USING ERRCODE='23514';END IF;UPDATE stock_adjustments SET status='PENDING' WHERE id=doc;
 ELSIF action IN('approve','reject') THEN
 IF d.status<>'PENDING' OR actor=d.created_by THEN RAISE EXCEPTION 'Independent adjustment approver required' USING ERRCODE='23514';END IF;
 IF action='reject' THEN UPDATE stock_adjustments SET status='REJECTED',review_note=note WHERE id=doc;
 ELSE
 IF NOT EXISTS(SELECT 1 FROM inventory_exceptions WHERE id=d.exception_id AND status NOT IN('RESOLVED','CLOSED')) THEN RAISE EXCEPTION 'Related exception is already closed' USING ERRCODE='23514';END IF;
 UPDATE stock_adjustments SET status='APPLIED',approved_by=actor,approved_at=v24_posting_time(),applied_revision=r,applied_txid=txid_current(),review_note=note,approved_attachments=coalesce((SELECT jsonb_agg(jsonb_build_object('id',id,'filename',filename,'sha256',sha256)) FROM workflow_attachments WHERE kind='adjustment' AND document_id=doc),'[]'::jsonb) WHERE id=doc;
 FOR l IN SELECT * FROM adjustment_lines WHERE adjustment_id=doc ORDER BY bundle_no LOOP
 IF NOT EXISTS(SELECT 1 FROM locations x JOIN warehouses w ON w.id=x.warehouse_id WHERE x.id=(l.after_data->>'location_id')::uuid AND x.project_id=d.project_id AND x.active AND w.active AND NOT EXISTS(SELECT 1 FROM yards y WHERE y.id=x.yard_id AND NOT y.active) FOR SHARE OF x,w) OR NOT EXISTS(SELECT 1 FROM customers WHERE id=(l.after_data->>'customer_id')::uuid AND active FOR SHARE) OR NOT EXISTS(SELECT 1 FROM batches WHERE id=(l.after_data->>'batch_id')::uuid AND active FOR SHARE) THEN RAISE EXCEPTION 'Adjustment target master data changed' USING ERRCODE='23514';END IF;
 qty:=(l.after_data->>'net_weight')::numeric;
 IF l.kind='GAIN' THEN
 IF EXISTS(SELECT 1 FROM receipt_lines q JOIN receipts qd ON qd.id=q.receipt_id WHERE q.bundle_no=l.bundle_no AND qd.status='PENDING') THEN RAISE EXCEPTION 'Pending receipt now uses gain number' USING ERRCODE='23514';END IF;
 INSERT INTO bundles(bundle_no,project_id,batch_id,location_id,customer_id,net_weight,physical_status,sample_status,inbound_date,inbound_at,data_kind,production_date,adjustment_origin_id,remark) VALUES(l.bundle_no,d.project_id,(l.after_data->>'batch_id')::uuid,(l.after_data->>'location_id')::uuid,(l.after_data->>'customer_id')::uuid,qty,'IN_STOCK','NOT_SAMPLED',(v24_posting_time() AT TIME ZONE 'Africa/Lubumbashi')::date,v24_posting_time(),CASE WHEN(SELECT environment FROM system_info)='test' THEN 'DEMO' ELSE 'REAL' END,(l.after_data->>'production_date')::date,doc,'授权盘盈调整：'||d.reason) RETURNING id INTO bid;delta:=qty;
 ELSE SELECT * INTO b FROM bundles WHERE bundle_no=l.bundle_no FOR UPDATE;
 IF NOT FOUND OR b.version<>l.expected_version OR b.physical_status<>l.before_data->>'physical_status' OR b.net_weight<>(l.before_data->>'net_weight')::numeric OR b.location_id<>(l.before_data->>'location_id')::uuid OR EXISTS(SELECT 1 FROM reservations WHERE bundle_id=b.id AND released_at IS NULL) OR EXISTS(SELECT 1 FROM loading_items WHERE bundle_id=b.id AND active) THEN RAISE EXCEPTION 'Inventory changed after draft; new authorized document required' USING ERRCODE='23514';END IF;
 bid:=b.id;delta:=CASE l.kind WHEN 'LOSS' THEN -b.net_weight WHEN 'RESTORE' THEN b.net_weight WHEN 'WEIGHT' THEN qty-b.net_weight ELSE 0 END;
 UPDATE bundles SET net_weight=qty,location_id=(l.after_data->>'location_id')::uuid,physical_status=l.after_data->>'physical_status',version=version+1 WHERE id=b.id;
 END IF;
 INSERT INTO inventory_events(bundle_id,event_type,physical_delta,actor_id,before_data,after_data) VALUES(bid,'ADJUST_'||l.kind,delta,actor,l.before_data,l.after_data||jsonb_build_object('adjustment_id',doc,'code',d.code,'reason',d.reason,'exception_id',d.exception_id));END LOOP;
 INSERT INTO exception_steps(exception_id,action,actor_id,note) VALUES(d.exception_id,'ADJUSTMENT_APPLIED',actor,d.code||'：'||note);
 END IF;
 ELSE RAISE EXCEPTION 'Unknown adjustment action' USING ERRCODE='23514';END IF;
 UPDATE stock_adjustments SET version=version+1 WHERE id=doc RETURNING * INTO d;INSERT INTO adjustment_steps(adjustment_id,action,actor_id,note) VALUES(doc,action,actor,note);INSERT INTO audit_logs(actor_id,action,entity_type,entity_id,after_data) VALUES(actor,'adjustment_'||action,'stock_adjustments',doc::text,to_jsonb(d));RETURN d;END $$;
CREATE FUNCTION adjustment_reverse(actor uuid,original uuid,exc uuid,reason text) RETURNS stock_adjustments LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,pg_temp AS $$ DECLARE d stock_adjustments;l adjustment_lines;b bundles;rows jsonb:='[]';x jsonb;BEGIN
 PERFORM v24_revision();SELECT * INTO d FROM stock_adjustments WHERE id=original AND status='APPLIED';IF NOT FOUND THEN RAISE EXCEPTION 'Only applied document can be reversed' USING ERRCODE='23514';END IF;PERFORM v23_require(actor,'adjust:write',d.project_id,NULL,NULL);
 FOR l IN SELECT * FROM adjustment_lines WHERE adjustment_id=original ORDER BY bundle_no LOOP SELECT * INTO b FROM bundles WHERE bundle_no=l.bundle_no;
 IF b.net_weight<>(l.after_data->>'net_weight')::numeric OR b.physical_status<>l.after_data->>'physical_status' OR(l.kind='LOCATION' AND b.location_id<>(l.after_data->>'location_id')::uuid) THEN RAISE EXCEPTION 'Original adjustment effects have changed; do not blindly reverse' USING ERRCODE='23514';END IF;
 x:=jsonb_build_object('bundle_no',l.bundle_no,'kind',CASE l.kind WHEN 'GAIN' THEN 'LOSS' WHEN 'LOSS' THEN 'RESTORE' WHEN 'RESTORE' THEN 'LOSS' ELSE l.kind END);IF l.kind='WEIGHT' THEN x:=x||jsonb_build_object('net_weight',l.before_data->>'net_weight');ELSIF l.kind='LOCATION' THEN x:=x||jsonb_build_object('location_id',l.before_data->>'location_id');END IF;rows:=rows||jsonb_build_array(x);END LOOP;
 RETURN adjustment_create(actor,d.project_id,exc,reason,rows,original);END $$;
REVOKE ALL ON FUNCTION adjustment_create(uuid,uuid,uuid,text,jsonb,uuid),adjustment_action(uuid,uuid,int,text,text),adjustment_reverse(uuid,uuid,uuid,text) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION adjustment_create(uuid,uuid,uuid,text,jsonb,uuid),adjustment_action(uuid,uuid,int,text,text),adjustment_reverse(uuid,uuid,uuid,text) TO musonoi_app;
GRANT SELECT ON stock_adjustments,adjustment_lines,adjustment_steps TO musonoi_app;
CREATE OR REPLACE VIEW inventory_view AS SELECT b.id AS uuid,b.bundle_no AS id,b.project_id,b.customer_id,l.warehouse_id,c.name AS customer,l.code AS location,t.code AS batch,b.net_weight AS weight,CASE WHEN b.physical_status='OUTBOUND' THEN '已出库' WHEN b.physical_status='ADJUSTED_OUT' THEN '已调整移出' WHEN r.id IS NOT NULL THEN '已预留' ELSE '在库' END AS status,CASE b.sample_status WHEN 'NOT_SAMPLED' THEN '未取样' WHEN 'SAMPLING' THEN '取样中' ELSE '已取样' END AS sample,to_char(b.inbound_date,'YYYY-MM-DD') AS date,b.grade,b.purity,b.data_kind,b.version,p.customer_id AS allocated_customer_id,ac.name AS allocated_customer,a.code AS allocation_code,p.code AS sales_plan_code,coalesce(doc.code,adj.code) AS receipt_code,coalesce(doc.confirmed_at,adj.approved_at) AS confirmed_at,to_char(b.production_date,'YYYY-MM-DD') AS production_date,b.inbound_at,coalesce(u.display_name,au.display_name) AS inbound_operator,b.remark,b.receipt_id,dispatch.customer_id AS dispatched_customer_id,dispatch.code AS outbound_code,dispatch.vehicle_no,dispatch.departed_at,dispatch.customer_name AS dispatched_customer,b.original_net_weight AS original_weight,adj.code AS adjustment_code,b.adjustment_origin_id FROM bundles b JOIN customers c ON c.id=b.customer_id JOIN locations l ON l.id=b.location_id JOIN batches t ON t.id=b.batch_id LEFT JOIN reservations r ON r.bundle_id=b.id AND r.released_at IS NULL LEFT JOIN allocations a ON a.id=r.allocation_id LEFT JOIN sales_plans p ON p.id=a.plan_id LEFT JOIN customers ac ON ac.id=p.customer_id LEFT JOIN receipts doc ON doc.id=b.receipt_id LEFT JOIN users u ON u.id=doc.created_by LEFT JOIN LATERAL(SELECT d.customer_id,d.code,d.departed_at,o.vehicle_no,c.name AS customer_name FROM outbound_orders d JOIN loading_orders o ON o.id=d.loading_id JOIN loading_items z ON z.loading_id=o.id JOIN customers c ON c.id=d.customer_id WHERE z.bundle_id=b.id AND d.status='DEPARTED' AND b.physical_status='OUTBOUND' ORDER BY d.departed_at DESC LIMIT 1) dispatch ON true LEFT JOIN stock_adjustments adj ON adj.id=b.adjustment_origin_id LEFT JOIN users au ON au.id=adj.created_by;
